void test_sensors_process_01(void)
{
    sensors_process(1999U);

    TEST_ASSERT_EQUAL_INT(0, frame_calls);
    TEST_ASSERT_EQUAL_INT(0, decode_calls);
    TEST_ASSERT_TRUE(!sensors_snapshot()->climate_valid);
    TEST_ASSERT_EQUAL_INT(0, log_calls);
}

void test_sensors_process_02(void)
{
    frame_result = false;
    sensors_process(2000U);

    TEST_ASSERT_EQUAL_INT(1, frame_calls);
    TEST_ASSERT_EQUAL_INT(0, decode_calls);
    TEST_ASSERT_TRUE(!sensors_snapshot()->climate_valid);
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->temperature_c));
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->humidity_percent));
}

void test_sensors_process_03(void)
{
    frame_result = true;
    frame_bytes[0] = 0x12U;
    frame_bytes[1] = 0x34U;
    frame_bytes[2] = 0x56U;
    frame_bytes[3] = 0x78U;
    frame_bytes[4] = 0x9AU;
    decode_result = false;
    sensors_process(2000U);

    TEST_ASSERT_EQUAL_INT(1, frame_calls);
    TEST_ASSERT_EQUAL_INT(1, decode_calls);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(frame_bytes, decoded_frame, 5U);
    TEST_ASSERT_TRUE(!sensors_snapshot()->climate_valid);
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->temperature_c));
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->humidity_percent));
}

void test_sensors_process_04(void)
{
    frame_result = true;
    frame_bytes[0] = 0x01U;
    frame_bytes[1] = 0x02U;
    frame_bytes[2] = 0x03U;
    frame_bytes[3] = 0x04U;
    frame_bytes[4] = 0x05U;
    decode_result = true;
    decode_temperature = 23.5F;
    decode_humidity = 47.25F;
    sensors_process(2000U);

    TEST_ASSERT_TRUE(sensors_snapshot()->climate_valid);
    TEST_ASSERT_EQUAL_FLOAT(23.5F, sensors_snapshot()->temperature_c);
    TEST_ASSERT_EQUAL_FLOAT(47.25F, sensors_snapshot()->humidity_percent);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(frame_bytes, decoded_frame, 5U);
}

void test_sensors_process_05(void)
{
    sensors_process(10U);

    TEST_ASSERT_TRUE(!sensors_snapshot()->acceleration_valid);
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->acceleration.x_g));
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->acceleration.y_g));
    TEST_ASSERT_TRUE(isnan(sensors_snapshot()->acceleration.z_g));
}

void test_sensors_process_06(void)
{
    sensors_process(1999U);
    TEST_ASSERT_EQUAL_INT(0, log_calls);

    sensors_process(2000U);

    TEST_ASSERT_EQUAL_STRING("SENSORS climate=0 imu=0 calibrated=0\r\n", last_log);
}
